fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Initialize min and max to the first element
    let mut min_val = x[0];
    let mut max_val = x[0];

    // Iterate through the rest of the vector, updating min and max
    for &v in &x[1..] {
        if v < min_val {
            min_val = v;
        }
        if v > max_val {
            max_val = v;
        }
    }

    // Return a two-element vector [min, max]
    vec![min_val, max_val]
}

